private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    while (bb.hasRemaining()) {
        byte b = bb.get();
        if ((b & 0x80) == 0) {
            // Single-byte character
            sb.append((char) b);
            i++;
        } else if ((b & 0xE0) == 0xC0) {
            // Two-byte character
            if (bb.remaining() < 1) break;
            sb.append((char) (((b & 0x1F) << 6) | (bb.get() & 0x3F)));
            i += 2;
        } else if ((b & 0xF0) == 0xE0) {
            // Three-byte character
            if (bb.remaining() < 2) break;
            sb.append((char) (((b & 0x0F) << 12) | ((bb.get() & 0x3F) << 6) | (bb.get() & 0x3F)));
            i += 3;
        } else if ((b & 0xF8) == 0xF0) {
            // Four-byte character
            if (bb.remaining() < 3) break;
            int codePoint = (((b & 0x07) << 18) | ((bb.get() & 0x3F) << 12) | ((bb.get() & 0x3F) << 6) | (bb.get() & 0x3F));
            sb.append(Character.toChars(codePoint));
            i += 4;
        } else {
            // Invalid UTF-8 sequence
            throw new IllegalArgumentException("Invalid UTF-8 sequence");
        }
    }
    return i;
}

