final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    int index = constantPoolEntryIndex + 1; // skip the tag byte
    int utfLength = (classFileBuffer[index++] & 0xFF) << 8 | (classFileBuffer[index++] & 0xFF);
    int utfIndex = 0;
    for (int i = 0; i < utfLength; ) {
        int byte1 = classFileBuffer[index++] & 0xFF;
        if ((byte1 & 0x80) == 0) {
            charBuffer[utfIndex++] = (char) byte1;
            i++;
        } else if ((byte1 & 0xE0) == 0xC0) {
            int byte2 = classFileBuffer[index++] & 0xFF;
            charBuffer[utfIndex++] = (char) (((byte1 & 0x1F) << 6) | (byte2 & 0x3F));
            i += 2;
        } else if ((byte1 & 0xF0) == 0xE0) {
            int byte2 = classFileBuffer[index++] & 0xFF;
            int byte3 = classFileBuffer[index++] & 0xFF;
            charBuffer[utfIndex++] = (char) (((byte1 & 0x0F) << 12) | ((byte2 & 0x3F) << 6) | (byte3 & 0x3F));
