private void pop(final String descriptor){
    // Assuming the descriptor is a method descriptor, we need to parse the argument types
    // and pop the corresponding number of elements from the output frame stack.
    // This is a simplified version and assumes the descriptor is well-formed.

    int index = 0;
    if (descriptor.charAt(0) == '(') {
        // It's a method descriptor, skip the '('
        index = 1;
    }

    while (index < descriptor.length() && descriptor.charAt(index) != ')') {
        char c = descriptor.charAt(index);
        switch (c) {
            case 'B': // byte
            case 'C': // char
            case 'D': // double
            case 'F': // float
            case 'I': // int
            case 'L': // long (reference, but treated as single slot here)
            case 'S': // short
            case 'Z': // boolean
                // These types occupy one slot
                // Pop one element from the stack
                popOneSlot();
                index++;
                break;
            case 'J': // long (double slot)
                // This type occupies two slots
                // Pop two elements from the stack
                popTwoSlots();
                index++;
                break;
            case '[': // array
                // Arrays are references and occupy one slot
                // Pop one element from the stack
                popOneSlot();
                // Skip the rest of the array descriptor
                while (descriptor.charAt(index) == '[') {
                    index++;
                }
                if (descriptor.charAt(index) == 'L') {
                    // Skip the class name
                    index = descriptor.indexOf(';', index) + 1;
                } else {
                    index++;
                }
                break;
            default:
                // Invalid descriptor character
                throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
        }
    }
}

